def in_square(p):
    return abs(p[0]) <= 2 and abs(p[1]) <= 2

def in_half_plane(p):
    return p[0] + p[1] <= 2

print(in_square((0.0, 0.0)), in_half_plane((0.5, 0.5)))   # True True : midpoints of members stay inside
print(in_square((1.5, -1.0)), in_half_plane((1.0, 0.5)))  # True True

